    struct sockaddr_in address;
    int opt = 1;
    int addrlen = sizeof(address);
    char buffer[BUFFER_SIZE] = {0};
    char response[BUFFER_SIZE];

    // Create socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    // Attach socket to the port
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt))) {
        perror("setsockopt");
        exit(EXIT_FAILURE);
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Bind the socket to the address
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        exit(EXIT_FAILURE);
    }

    // Start listening for connections
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        exit(EXIT_FAILURE);
    }

    printf("Server is listening on port %d\n", PORT);

    while (1) {
        // Accept a new connection
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept");
            exit(EXIT_FAILURE);
        }

        // Fork a new process to handle the client
        if (fork() == 0) {
            // Child process
            close(server_fd); // Close the listening socket in the child process

            // Read command from client
            int valread = read(new_socket, buffer, BUFFER_SIZE);
            buffer[valread] = '\0'; // Null-terminate the string

            // Process the command
            process_command(buffer, response);

            // Send response back to client
            send(new_socket, response, strlen(response), 0);
            close(new_socket); // Close the client socket
            exit(0); // Exit child process
        } else {
            // Parent process
            close(new_socket); // Close the client socket in the parent process
        }
    }

    return 0;
}
```

### Explanation:
1. **Socket Creation**: The server creates a TCP socket.
2. **Binding**: It binds the socket to a specified port (8080 in this case).
3. **Listening**: The server listens for incoming connections

