Creating a web application in C that handles user authentication involves several components, including handling HTTP requests, managing user sessions, and securely storing passwords. Below is a simplified example of how you might implement basic user authentication in a C web application using the CGI (Common Gateway Interface) approach. This example does not include all security best practices and is meant for educational purposes only.

### Example Code for User Authentication in C

1. **Install Required Libraries**: Make sure you have a web server that supports CGI (like Apache) and the necessary libraries for handling HTTP requests.

2. **Create a Simple CGI Script**: Below is a basic example of a CGI script that handles user login.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define USERNAME "admin"
#define PASSWORD "password" // In a real application, use hashed passwords

void print_header() {
    printf("Content-Type: text/html\n\n");
}

void print_login_form() {
    printf("<html><body>");
    printf("<h2>Login</h2>");
    printf("<form method='POST' action='auth.cgi'>");
    printf("Username: <input type='text' name='username'><br>");
    printf("Password: <input type='password' name='password'><br>");
    printf("<input type='submit' value='Login'>");
    printf("</form></body></html>");
}

int main() {
    char *request_method = getenv("REQUEST_METHOD");
    if (request_method == NULL) {
        print_header();
        printf("Error: No request method found.");
        return 1;
    }

    if (strcmp(request_method, "GET") == 0) {
        print_header();
        print_login_form();
    } else if (strcmp(request_method, "POST") == 0) {
        char *data = getenv("QUERY_STRING");
        if (data == NULL) {
            print_header();
            printf("Error: No data received.");
            return 1;
        }

        char username[100], password[100];
        sscanf(data, "username=%99[^&]&password=%99s", username, password);

        if (strcmp(username, USERNAME) == 0 && strcmp(password, PASSWORD) == 0) {
            print_header();
            printf("<h2>Login successful!</h2>");
        } else {
            print_header();
            printf("<h2>Login failed. Please try again.</h2>");
            print_login_form();
        }
    } else {
        print_header();
        printf("Error: Unsupported request method.");
    }

    return 0;
}
```

