### Simple TCP Server in C

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/types.h>
#include <sys/socket.h>

#define PORT 8080
#define BUFFER_SIZE 1024

void process_command(int client_socket, const char *command) {
    char response[BUFFER_SIZE];

    // Simple command processing
    if (strcmp(command, "HELLO") == 0) {
        snprintf(response, sizeof(response), "Hello, Client!\n");
    } else if (strcmp(command, "TIME") == 0) {
        time_t now = time(NULL);
        snprintf(response, sizeof(response), "Current time: %s", ctime(&now));
    } else {
        snprintf(response, sizeof(response), "Unknown command: %s\n", command);
    }

    send(client_socket, response, strlen(response), 0);
}

int main() {
    int server_socket, client_socket;
    struct sockaddr_in server_addr, client_addr;
    socklen_t addr_len = sizeof(client_addr);
    char buffer[BUFFER_SIZE];

    // Create socket
    if ((server_socket = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }

    // Set up the server address structure
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    // Bind the socket
    if (bind(server_socket, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Bind failed");
        close(server_socket);
        exit(EXIT_FAILURE);
    }

    // Listen for incoming connections
    if (listen(server_socket, 3) < 0) {
        perror("Listen failed");
        close(server_socket);
        exit(EXIT_FAILURE);
    }

    printf("Server is listening on port %d\n", PORT);

    while (1) {
        // Accept a new client connection
        if ((client_socket = accept(server_socket, (struct sockaddr *)&client_addr, &addr_len)) < 0) {
            perror("Accept failed");
            continue;
        }

        // Fork a new process to handle the client
        if (fork() == 0) {
            // Child process
            close(server_socket); // Close the listening socket in the child process

            // Receive command from the client
            int bytes_received = recv(client_socket, buffer, BUFFER_SIZE - 1, 0);
            if (bytes_received > 0) {
                buffer[bytes_received] = '\0'; // Null-terminate the received string
                printf("Received command: %s", buffer);
                process_command(client_socket, buffer);
            }

            close(client_socket); // Close the client socket
            exit(0); // Exit the child process
        } else {
            // Parent process
            close(client_socket); // Close the client socket in the parent process
        }
    }

    close(server_socket); // Close the server socket

