Sure! Below is a simple example of a network server written in C that can receive commands from clients and process them. This server uses TCP sockets and can handle multiple clients using `fork()`.

### Simple TCP Server in C

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>

#define PORT 8080
#define BUFFER_SIZE 1024

void process_command(const char *command, char *response) {
    // Simple command processing
    if (strcmp(command, "hello") == 0) {
        strcpy(response, "Hello, client!");
    } else if (strcmp(command, "bye") == 0) {
        strcpy(response, "Goodbye, client!");
    } else {
        strcpy(response, "Unknown command.");
    }
}

int main() {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int opt = 1;
    int addrlen = sizeof(address);
    char buffer[BUFFER_SIZE] = {0};
    char response[BUFFER_SIZE];

    // Create socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    // Attach socket to the port
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt))) {
        perror("setsockopt");
        exit(EXIT_FAILURE);
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Bind the socket to the address
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        exit(EXIT_FAILURE);
    }

    // Start listening for connections
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        exit(EXIT_FAILURE);
    }

    printf("Server is listening on port %d\n", PORT);

    while (1) {
        // Accept a new connection
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept");
            exit(EXIT_FAILURE);
        }

        // Fork a new process to handle the client
        if (fork() == 0) {
            close(server_fd); // Child process doesn't need the listener

            // Read command from client
            int valread = read(new_socket, buffer, BUFFER_SIZE);
            buffer[valread] = '\0'; // Null-terminate the string

            // Process the command
            process_command(buffer, response);

            // Send response back to client
            send(new_socket, response, strlen(response), 0);
            printf("Response sent: %s\n", response);

            close(new_socket); // Close the socket in the child process
            exit(0); // Exit child process
        }

        close(new_socket); // Parent process closes the socket
    }

    return 0;
}
```

### How to Compile and Run

1. Save the code to a file named `server.c`.
2. Open a terminal and navigate to the directory where `server.c` is located.
3. Compile the code using:
   ```bash
   gcc server.c

